import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Embarcacion } from '../../embarcaciones/entities/embarcacion.entity';
import { Tripulante } from '../../tripulantes/entities/tripulante.entity';

@Injectable()
export class AsignarTripulanteRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Embarcacion) private readonly embarcaciones: Repository<Embarcacion>,
    @InjectRepository(Tripulante) private readonly tripulantes: Repository<Tripulante>
  ) {}

  buscarEmbarcacionRepository(embarcacionId: number) {
    return this.embarcaciones.findOneBy({ id: embarcacionId });
  }

  buscarTripulanteRepository(tripulanteId: number) {
    return this.tripulantes.findOneBy({ id: tripulanteId });
  }

  async asignarTripulanteRepository(embarcacionId: number, tripulanteId: number, rol: string) {
    const asignacion = { embarcacionId, tripulanteId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarTripulanteRepository } from './repository';

@Injectable()
export class AsignarTripulanteService {
  constructor(private readonly repository: AsignarTripulanteRepository) {}

  async asignarTripulanteService(embarcacionId: number, tripulanteId: number, rol: string) {
    const embarcacion = await this.repository.buscarEmbarcacionRepository(embarcacionId);
    const tripulante = await this.repository.buscarTripulanteRepository(tripulanteId);
    if (!embarcacion || !tripulante) {
      throw new NotFoundException('No existe la embarcacion o el tripulante');
    }

    try {
      return await this.repository.asignarTripulanteRepository(embarcacionId, tripulanteId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El tripulante ya está asignado a esa embarcacion');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarTripulanteService } from './service';

@Controller('embarcaciones/:embarcacionId/asignaciones')
export class AsignarTripulanteController {
  constructor(private readonly service: AsignarTripulanteService) {}

  @Post()
  asignar(@Param('embarcacionId') embarcacionId: string, @Body() datos: { tripulanteId: number; rol: string }) {
    return this.service.asignarTripulanteService(Number(embarcacionId), datos.tripulanteId, datos.rol);
  }
}
